/* ===== tokens.css ===== */
/*
 * 星票奶铺 / Milk Ledger
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 * 第三方字体与素材继续遵守其原许可证。
 */

@font-face {
    font-family: "LXGW WenKai";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/lxgwwenkai/lxgwwenkai.woff2") format("woff2");
    font-weight: 400;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: "Love Ya Like A Sister";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/love-ya-like-a-sister/LoveYaLikeASister-Regular.woff2") format("woff2");
    font-weight: 400;
    font-style: normal;
    font-display: swap;
}

:root {
    --ml-navy: #263b48;
    --ml-navy-deep: #1e303b;
    --ml-blue: #6f91a3;
    --ml-blue-pale: #a9c2ca;
    --ml-cream: #f4e6c2;
    --ml-cream-pale: #fff3d8;
    --ml-brick: #9a4933;
    --ml-brick-deep: #733124;
    --ml-cocoa: #4a271f;
    --ml-ink: #342923;
    --ml-muted: #607b88;
    --ml-success: #64806b;
    --ml-warning: #a87539;
    --ml-error: #a44939;
    --ml-info: #608295;
    --ml-line: 2px solid var(--ml-cocoa);
    --ml-hairline: 1px solid rgb(74 39 31 / 52%);
    --ml-radius: 2px;
    --ml-shadow: 0 6px 0 rgb(74 39 31 / 17%);
    --ml-font-body: "LXGW WenKai", "Microsoft YaHei UI", "PingFang SC", sans-serif;
    --ml-font-label: "Love Ya Like A Sister", "LXGW WenKai", "Microsoft YaHei UI", sans-serif;
    --avatar-size: clamp(3.15rem, 5.8vw, 4.65rem);
    --avatar-gap: 0.55rem;
    --avatar-slot: calc(var(--avatar-size) + var(--avatar-gap));
    --ml-asset-paper: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/06ca4dbf4f6dbea49bda3dc00fc2f56326bbe2a8/assets/%E6%98%9F%E7%A5%A8%E5%A5%B6%E9%93%BA/ledger-paper.png");
    --ml-asset-topbar: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/06ca4dbf4f6dbea49bda3dc00fc2f56326bbe2a8/assets/%E6%98%9F%E7%A5%A8%E5%A5%B6%E9%93%BA/topbar-objects.png");
    --ml-asset-counter: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/06ca4dbf4f6dbea49bda3dc00fc2f56326bbe2a8/assets/%E6%98%9F%E7%A5%A8%E5%A5%B6%E9%93%BA/counter-objects.png");
}

body {
    color: var(--ml-ink);
    background-color: var(--ml-cream);
    font-family: var(--ml-font-body);
}


/* ===== kernel/function-protection.css ===== */
/* Functional guardrails and state fallbacks. No theme geometry belongs here. */

#top-settings-holder .drawer-toggle,
#send_form #options_button,
#send_form #send_but,
#send_form #mes_stop,
#send_form .fa-wand-magic,
#send_form .fa-wand-magic-sparkles {
    min-inline-size: 2.25rem;
    min-block-size: 2.25rem;
}

#top-settings-holder .drawer-icon:focus-visible,
#send_form .interactable:focus-visible,
#send_form .mes_stop:focus-visible,
#chat .mes_button:focus-visible,
.popup button:focus-visible,
.menu_button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
    outline: 2px solid var(--ml-cream);
    outline-offset: 2px;
}

#chat .mes_text,
#chat .mes_reasoning {
    overflow-wrap: anywhere;
}

#chat .mes_text pre,
#chat .mes_text table {
    max-inline-size: 100%;
    overflow: auto;
}

#chat .mes_media_wrapper img,
#chat .mes_text img,
#chat .mes_file_wrapper {
    max-inline-size: 100%;
}

#top-settings-holder .drawer-icon,
#send_form #options_button,
#send_form #send_but,
#send_form #mes_stop,
#send_form .fa-wand-magic,
#send_form .fa-wand-magic-sparkles {
    background-repeat: no-repeat;
    pointer-events: auto;
}


/* ===== chat-layout.css ===== */
/* W01: centered milk-ledger chat shell. Structure gate: confirmed. */

#bg1,
#bg_custom {
    background-color: var(--ml-cream);
    background-image:
        linear-gradient(rgb(244 230 194 / 74%), rgb(244 230 194 / 74%)),
        var(--ml-asset-paper);
    background-size: auto, min(58rem, 100vw) auto;
    background-position: center top;
}

#chat {
    gap: clamp(0.85rem, 2vw, 1.45rem);
    padding: clamp(0.85rem, 2.2vw, 1.75rem);
    color: var(--ml-ink);
    background-color: var(--ml-cream);
    background-image:
        linear-gradient(rgb(244 230 194 / 78%), rgb(244 230 194 / 78%)),
        var(--ml-asset-paper);
    background-size: auto, min(62rem, 118vw) auto;
    background-position: center top;
    text-shadow: none;
    scrollbar-color: var(--ml-blue) var(--ml-cream-pale);
}

#chat::before {
    content: "MILK BAR LEDGER · 星票奶铺";
    display: block;
    align-self: center;
    inline-size: min(92%, 54rem);
    padding: 0.7em 1.1em 0.58em;
    color: var(--ml-cream-pale);
    background: var(--ml-navy);
    border-block: 0.3rem double var(--ml-cream);
    outline: 1px solid var(--ml-cocoa);
    font-family: var(--ml-font-label);
    font-size: clamp(0.88rem, 1.8vw, 1.16rem);
    letter-spacing: 0.12em;
    text-align: center;
    box-shadow: var(--ml-shadow);
}

#chat .mes {
    flex-direction: column;
    align-items: stretch;
    align-self: center;
    inline-size: 100%;
    max-inline-size: 92%;
    margin: 0;
    padding: clamp(0.75rem, 1.7vw, 1.25rem);
    color: var(--ml-ink);
    background-color: var(--ml-cream-pale);
    background-image:
        linear-gradient(rgb(255 243 216 / 88%), rgb(255 243 216 / 88%)),
        var(--ml-asset-paper);
    background-size: auto, 50rem auto;
    border: var(--ml-line);
    border-block: 0.34rem double var(--ml-brick);
    border-radius: var(--ml-radius);
    box-shadow: var(--ml-shadow);
}

#chat .mes[is_user="true"] {
    max-inline-size: min(66%, 44rem);
    color: var(--ml-cream-pale);
    background-color: var(--ml-brick);
    background-image:
        linear-gradient(rgb(154 73 51 / 91%), rgb(154 73 51 / 91%)),
        var(--ml-asset-paper);
    border-color: var(--ml-cream);
    border-block-style: dashed;
    outline: 1px solid var(--ml-cocoa);
}

#chat .mes[is_system="true"] {
    max-inline-size: min(82%, 54rem);
    color: var(--ml-cream-pale);
    background: var(--ml-muted);
    border-style: dashed;
    box-shadow: none;
}

#chat .mes.smallSysMes {
    padding: 0.65em 1em !important;
}

#chat .mes.selected {
    background-color: var(--ml-warning);
    outline: 3px solid var(--ml-navy);
    outline-offset: 3px;
}

#chat .mes .mesAvatarWrapper {
    display: grid;
    flex: 0 0 auto;
    grid-template-columns: repeat(3, max-content);
    justify-content: center;
    align-items: center;
    gap: 0.35em;
    inline-size: 100%;
    min-block-size: var(--avatar-slot);
    margin: 0 0 0.4em;
    padding: 0;
    font-family: var(--ml-font-label);
}

#chat .mes .mesAvatarWrapper .avatar {
    display: block !important;
    grid-column: 1 / -1;
    justify-self: center;
    inline-size: var(--avatar-size);
    block-size: var(--avatar-size);
    margin: 0.1rem 0 0.25rem;
    overflow: hidden;
    background: var(--ml-blue-pale);
    border: 0.3rem double var(--ml-brick);
    border-radius: 50%;
    box-shadow: 0 0 0 0.18rem var(--ml-cream), 0 4px 0 rgb(74 39 31 / 18%);
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
    border-color: var(--ml-cream-pale);
    box-shadow: 0 0 0 0.18rem var(--ml-cocoa), 0 4px 0 rgb(74 39 31 / 25%);
}

#chat .mes .mesAvatarWrapper .avatar img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
}

#chat .mes .mes_timer,
#chat .mes .mesIDDisplay,
#chat .mes .tokenCounterDisplay {
    padding: 0.08em 0.45em;
    color: inherit;
    background: rgb(169 194 202 / 36%);
    border: 1px dashed currentColor;
    opacity: 0.8;
    font-size: 0.72em;
    font-weight: 400;
}

#chat .mes[is_user="true"] .mes_timer,
#chat .mes[is_user="true"] .mesIDDisplay,
#chat .mes[is_user="true"] .tokenCounterDisplay {
    background: rgb(74 39 31 / 25%);
}

#chat .mes_block {
    flex: 1 1 auto;
    min-inline-size: 0;
    inline-size: 100%;
    padding: 0;
}

#chat .mes_block .ch_name {
    justify-content: center;
    min-block-size: 0;
    margin: 0 0 0.75em;
    padding-block: 0.42em;
    border-block: 1px dashed currentColor;
    font-family: var(--ml-font-label);
    letter-spacing: 0.055em;
    text-align: center;
}

#chat .mes_block .name_text {
    font-size: 1.08em;
    font-weight: 400;
    text-transform: uppercase;
}

#chat .mes_block .timestamp {
    color: inherit;
    opacity: 0.68;
    font-size: 0.76em;
}

#chat .mes_buttons,
#chat .extraMesButtons {
    color: inherit;
    overflow-x: auto;
}

#chat .mes_button,
#chat .extraMesButtons > div {
    color: inherit;
    filter: none;
    opacity: 0.5;
}

#chat .mes_button:hover,
#chat .mes_button:focus-visible,
#chat .extraMesButtons > div:hover,
#chat .extraMesButtons > div:focus-visible {
    opacity: 1;
}

#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter {
    color: currentColor;
    filter: none;
}

#chat .mes_reasoning_details {
    margin: 0.45em 0 0.8em;
    padding: 0.65em 0.8em;
    color: var(--ml-ink);
    background: rgb(169 194 202 / 42%);
    border: 1px dashed var(--ml-cocoa);
}

#chat .mes_reasoning_details[data-state="thinking"] {
    color: var(--ml-cream-pale);
    background: var(--ml-navy);
    border-color: var(--ml-cream);
}


/* ===== full-text.css ===== */
/* T01: traditional ledger typography. Parent geometry stays in chat-layout.css. */

#chat .mes_text {
    inline-size: 100%;
    max-inline-size: 72ch;
    margin-inline: auto;
    padding: 0.2em 0 0.5em;
    color: inherit;
    font-family: var(--ml-font-body);
    font-size: 1em;
    font-weight: 400;
    line-height: 1.82;
    text-align: start;
}

#chat .mes[is_user="true"] .mes_text {
    max-inline-size: 58ch;
    line-height: 1.64;
    text-align: center;
}

#chat .mes_text p {
    margin-block: 0 0.94em;
}

#chat .mes_text p:last-child {
    margin-block-end: 0;
}

#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4 {
    margin: 1.2em 0 0.62em;
    color: var(--ml-brick-deep);
    font-family: var(--ml-font-label);
    font-weight: 400;
    line-height: 1.25;
    letter-spacing: 0.05em;
    text-align: center;
}

#chat .mes[is_user="true"] .mes_text h1,
#chat .mes[is_user="true"] .mes_text h2,
#chat .mes[is_user="true"] .mes_text h3,
#chat .mes[is_user="true"] .mes_text h4 {
    color: var(--ml-cream);
}

#chat .mes_text blockquote {
    margin: 1em 0;
    padding: 0.7em 1em;
    color: var(--ml-cocoa);
    background: rgb(169 194 202 / 27%);
    border: 0;
    border-block: 1px dashed var(--ml-brick);
}

#chat .mes[is_user="true"] .mes_text blockquote {
    color: var(--ml-cream-pale);
    background: rgb(74 39 31 / 24%);
    border-color: var(--ml-blue-pale);
}

#chat .mes_text strong {
    color: var(--ml-brick-deep);
    font-weight: 400;
    text-decoration: underline;
    text-decoration-thickness: 0.12em;
    text-underline-offset: 0.16em;
}

#chat .mes[is_user="true"] .mes_text strong {
    color: var(--ml-cream);
}

#chat .mes_text em {
    color: var(--ml-muted);
}

#chat .mes_text a {
    color: var(--ml-brick-deep);
    text-decoration-style: dotted;
    text-underline-offset: 0.18em;
}

#chat .mes[is_user="true"] .mes_text a {
    color: var(--ml-blue-pale);
}

#chat .mes_text code,
#chat .mes_text pre {
    color: var(--ml-cream-pale);
    background: var(--ml-navy-deep);
    border-color: var(--ml-blue);
    border-radius: var(--ml-radius);
    font-family: var(--ml-font-label);
    text-shadow: none;
}

#chat .mes_text pre {
    padding: 0.9em 1em;
}

#chat .mes_text table {
    border-collapse: collapse;
    color: var(--ml-ink);
    background: rgb(255 243 216 / 82%);
}

#chat .mes_text th,
#chat .mes_text td {
    padding: 0.45em 0.65em;
    border: var(--ml-hairline);
}

#chat .mes_text th {
    color: var(--ml-cream-pale);
    background: var(--ml-navy);
    font-family: var(--ml-font-label);
    font-weight: 400;
}

#chat .mes_text hr {
    block-size: 0.38em;
    margin-block: 1.45em;
    border: 0;
    border-block: 1px dashed currentColor;
    opacity: 0.68;
}

#chat .mes_text details {
    margin-block: 0.75em;
    padding: 0.6em 0.75em;
    border: 1px dashed currentColor;
}


/* ===== windows/top-bar.css ===== */
/* W02: nine unframed milk-bar objects. Native glyphs remain as image-failure fallback. */

#top-bar {
    background-color: var(--ml-cream-pale);
    background-image:
        linear-gradient(rgb(255 243 216 / 78%), rgb(255 243 216 / 78%)),
        var(--ml-asset-paper);
    background-size: auto, 38rem auto;
    border-block-end: 0.3rem double var(--ml-brick);
    box-shadow: 0 4px 0 var(--ml-blue);
    backdrop-filter: none;
}

#top-settings-holder .drawer-toggle {
    background: transparent;
    border: 0;
    box-shadow: none;
}

#top-settings-holder .drawer-icon {
    color: rgb(74 39 31 / 26%);
    background-color: transparent;
    background-image: var(--ml-asset-topbar);
    background-size: 300% 300%;
    background-origin: content-box;
    background-clip: content-box;
    border: 0;
    border-radius: 0;
    filter: saturate(0.92);
    opacity: 0.92;
    text-shadow: none;
    transition: filter 150ms ease, opacity 150ms ease, transform 150ms ease;
}

#top-settings-holder .drawer-icon:hover,
#top-settings-holder .drawer-icon:focus-visible,
#top-settings-holder .drawer-icon.openIcon {
    filter: saturate(1.08) brightness(1.05);
    opacity: 1;
    transform: translateY(-0.08em) rotate(-1deg) scale(1.06);
}

#ai-config-button .drawer-icon { background-position: 0% 0%; }
#sys-settings-button .drawer-icon { background-position: 50% 0%; }
#advanced-formatting-button .drawer-icon { background-position: 100% 0%; }
#WI-SP-button .drawer-icon { background-position: 0% 50%; }
#user-settings-button .drawer-icon { background-position: 50% 50%; }
#backgrounds-button .drawer-icon { background-position: 100% 50%; }
#extensions-settings-button .drawer-icon { background-position: 0% 100%; }
#persona-management-button .drawer-icon { background-position: 50% 100%; }
#rightNavHolder .drawer-icon { background-position: 100% 100%; }


/* ===== windows/input.css ===== */
/* W03: milk-bar order-counter input area. */

#send_form {
    color: var(--ml-cream-pale);
    background-color: var(--ml-navy);
    background-image:
        linear-gradient(rgb(38 59 72 / 88%), rgb(38 59 72 / 88%)),
        var(--ml-asset-paper);
    background-size: auto, 46rem auto;
    border: var(--ml-line);
    border-block-start: 0.38rem double var(--ml-cream);
    border-radius: 0;
    box-shadow: 0 -4px 0 var(--ml-brick);
    backdrop-filter: none;
}

#send_form #nonQRFormItems {
    align-items: stretch;
    column-gap: 0.2em;
}

#send_textarea {
    color: var(--ml-ink);
    background: rgb(255 243 216 / 91%);
    border-inline: 1px dashed var(--ml-brick);
    font-family: var(--ml-font-body);
    font-size: 1em;
    text-shadow: none;
    caret-color: var(--ml-brick);
}

#send_textarea::placeholder {
    color: var(--ml-muted);
    opacity: 0.82;
}

#send_form:has(#send_textarea:focus-visible) {
    border-color: var(--ml-brick);
    outline: 2px solid var(--ml-cream);
    outline-offset: 2px;
}

#send_form #options_button,
#send_form #send_but,
#send_form #mes_stop,
#send_form .fa-wand-magic,
#send_form .fa-wand-magic-sparkles {
    color: rgb(255 243 216 / 26%);
    background-color: transparent;
    background-image: var(--ml-asset-counter);
    background-size: 200% 200%;
    background-origin: content-box;
    background-clip: content-box;
    border: 0;
    filter: none;
    opacity: 0.94;
    text-shadow: none;
    transition: filter 150ms ease, opacity 150ms ease, transform 150ms ease;
}

#send_form #options_button { background-position: 0% 0%; }
#send_form .fa-wand-magic,
#send_form .fa-wand-magic-sparkles { background-position: 100% 0%; }
#send_form #send_but { background-position: 0% 100%; }
#send_form #mes_stop { background-position: 100% 100%; }

#send_form #options_button:hover,
#send_form #send_but:hover,
#send_form #mes_stop:hover,
#send_form .fa-wand-magic:hover,
#send_form .fa-wand-magic-sparkles:hover,
#send_form #options_button:focus-visible,
#send_form #send_but:focus-visible,
#send_form #mes_stop:focus-visible {
    filter: brightness(1.08) saturate(1.08);
    opacity: 1;
    transform: rotate(-1deg) scale(1.06);
}

#form_sheld.script_success #send_textarea { --progSuccessColor: var(--ml-success); }
#form_sheld.script_error #send_textarea { --progErrorColor: var(--ml-error); }
#form_sheld.script_aborted #send_textarea { --progAbortedColor: var(--ml-warning); }


/* ===== windows/text-generation.css ===== */
/* W04: text-completion parameters. */

#left-nav-panel,
#textgenerationwebui_api-settings {
    color: var(--ml-ink);
    background-color: var(--ml-cream-pale);
    background-image:
        linear-gradient(rgb(247 237 208 / 94%), rgb(247 237 208 / 94%)),
        var(--ml-asset-paper);
    background-size: auto, 46rem auto;
    border-color: var(--ml-cocoa);
    box-shadow: inset 0.42rem 0 0 var(--ml-blue), inset -0.12rem 0 0 var(--ml-brick);
    backdrop-filter: none;
}

#left-nav-panel .scrollableInner,
#textgenerationwebui_api-settings {
    scrollbar-color: var(--ml-brick) var(--ml-cream);
}

#left-nav-panel .standoutHeader,
#left-nav-panel h3,
#left-nav-panel h4,
#textgenerationwebui_api-settings .standoutHeader {
    color: var(--ml-cream-pale);
    background: var(--ml-brick);
    border-block: 1px dashed var(--ml-cream);
    font-family: var(--ml-font-label);
    font-weight: 400;
    letter-spacing: 0.04em;
}

#left-nav-panel input,
#left-nav-panel textarea,
#left-nav-panel select,
#textgenerationwebui_api-settings input,
#textgenerationwebui_api-settings textarea,
#textgenerationwebui_api-settings select {
    color: var(--ml-ink);
    background: var(--ml-cream);
    border-color: var(--ml-cocoa);
    border-radius: var(--ml-radius);
    font-family: var(--ml-font-body);
}

#left-nav-panel option,
#left-nav-panel optgroup,
#textgenerationwebui_api-settings option,
#textgenerationwebui_api-settings optgroup {
    color: var(--ml-ink);
    background: var(--ml-cream-pale);
}

#left-nav-panel .menu_button,
#textgenerationwebui_api-settings .menu_button {
    color: var(--ml-cream-pale);
    background: var(--ml-muted);
    border-color: var(--ml-cocoa);
    box-shadow: none;
}


/* ===== windows/api-connection.css ===== */
/* W05: API connection, scoped to its actual component root. */

#rm_api_block {
    color: var(--ml-ink);
    background-color: var(--ml-cream-pale);
    background-image:
        linear-gradient(rgb(247 237 208 / 95%), rgb(247 237 208 / 95%)),
        var(--ml-asset-paper);
    background-size: auto, 48rem auto;
    border-color: var(--ml-cocoa);
    box-shadow: inset 0.42rem 0 0 var(--ml-brick);
    backdrop-filter: none;
}

#rm_api_block h3,
#rm_api_block h4,
#rm_api_block .standoutHeader,
#rm_api_block .inline-drawer-header {
    color: var(--ml-brick-deep);
    font-family: var(--ml-font-label);
    font-weight: 400;
    border-block-end: 1px dashed var(--ml-brick);
}

#rm_api_block input,
#rm_api_block textarea,
#rm_api_block select {
    color: var(--ml-ink);
    background: var(--ml-cream);
    border-color: var(--ml-cocoa);
    border-radius: var(--ml-radius);
}

#rm_api_block option,
#rm_api_block optgroup {
