    filter: none;
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #rm_extensions_block, #PersonaManagement, #right-nav-panel) input[type="checkbox"],
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #rm_extensions_block, #PersonaManagement, #right-nav-panel) input[type="radio"] {
