    border: 1px dashed var(--ml-muted);
    filter: none;
    opacity: 0.78;
    text-shadow: none;
}


/* ===== windows/mobile.css ===== */
/* W14: conservative single-column mobile fallback based on official <=700px shell. */

@media (max-width: 700px) {
    :root {
        --avatar-size: 3rem;
        --avatar-gap: 0.42rem;
    }

    #chat {
        gap: 0.72rem;
        padding: 0.55rem;
        background-size: auto, 42rem auto;
    }

    #chat::before {
        inline-size: 100%;
        padding-inline: 0.65em;
        letter-spacing: 0.07em;
    }

    #chat .mes,
    #chat .mes[is_user="true"],
    #chat .mes[is_system="true"] {
        align-self: stretch;
        inline-size: 100%;
        max-inline-size: 100%;
        margin-inline: 0;
        padding: 0.72rem;
    }

    #chat .mes_block .ch_name {
        flex-wrap: wrap;
        justify-content: center;
        row-gap: 0.3em;
    }

    #chat .mes_text,
    #chat .mes[is_user="true"] .mes_text {
        max-inline-size: 100%;
        line-height: 1.7;
    }

    #chat .mes_buttons,
    #chat .extraMesButtons {
        max-inline-size: 100%;
        overflow-x: auto;
    }

    #send_form {
        border-inline-width: 1px;
        box-shadow: 0 -3px 0 var(--ml-brick);
    }

    #send_form #leftSendForm,
    #send_form #rightSendForm {
        inline-size: auto;
        min-inline-size: 2.25rem;
    }

    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel {
        box-shadow: inset 0 0.32rem 0 var(--ml-brick);
        background-size: auto, 36rem auto;
    }

    .popup,
    .popup-content {
        max-inline-size: calc(100dvw - 1rem);
        max-block-size: calc(100dvh - 1rem);
        overflow: auto;
    }
}


